fn min(a: &Vec<i32>, n: usize) -> i32 {
    // Precondition (by problem statement): 0 < n <= a.len()
    // We can optionally enforce it at runtime:
    assert!(n > 0 && n <= a.len(), "n must be positive and at most the length of a");

    // Initialize the minimum with the first element
    let mut current_min = a[0];

    // Scan through the remaining first n elements
    for i in 1..n {
        if a[i] < current_min {
            current_min = a[i];
        }
    }

    current_min
}

